import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

interface ModeState {
    limits: GeospatialLimits;
    radius: number;
    yaw: number;
}

const states = new WeakMap<GeospatialCamera, ModeState>();

function clamp(value: number, min: number, max: number): number {
    return Math.min(max, Math.max(min, value));
}

function installAccessors(camera: GeospatialCamera, state: ModeState): void {
    Object.defineProperty(camera, "radius", {
        configurable: true,
        enumerable: true,
        get: () => state.radius,
        set: (value: number) => {
            state.radius = clamp(value, state.limits.radiusMin, state.limits.radiusMax);
        },
    });
    Object.defineProperty(camera, "yaw", {
        configurable: true,
        enumerable: true,
        get: () => state.yaw,
        set: (value: number) => {
            state.yaw = clamp(value, state.limits.yawMin, state.limits.yawMax);
        },
    });
}

export function useModeLimits(camera: GeospatialCamera, limits: GeospatialLimits): void {
    let state = states.get(camera);
    if (!state) {
        state = { limits, radius: camera.radius, yaw: camera.yaw };
        states.set(camera, state);
        installAccessors(camera, state);
    }
    // Never mutate the mode's limits object; only switch which one is active.
    state.limits = limits;
    state.radius = clamp(state.radius, limits.radiusMin, limits.radiusMax);
    state.yaw = clamp(state.yaw, limits.yawMin, limits.yawMax);
    camera.limits = limits;
}
```

I wrote this from the declarations pasted in your message, since I can't open the file in this reply, and I have not saved it to /home/dev/a863a6/app/src/mode-limits.ts. The approach wraps `radius` and `yaw` on the camera with accessors that clamp to the active mode's `radiusMin`/`radiusMax` and `yawMin`/`yawMax`, then sets `camera.limits` to that mode's object.

Things I'm not sure of:
- The wrappers only work if the library reads and writes `camera.radius` and `camera.yaw` as properties on the camera object. If its internals (`_setOrientation`, inertia, fly animations) keep their own copies, they could bypass the clamp.
- I don't know whether the library's own `clampZoomDistance` (which accounts for pitch and collisions) should be used instead of the plain min/max clamp. I used the plain clamp.
- Yaw is clamped without wrapping, so a heading range that crosses the ±π seam would not behave as a wrap-around range.
- If the camera object is frozen or non-configurable, `defineProperty` will throw.
